// [S4] Static referral path. No AI-generated guidance appears here.
//
// Clinical Rule 10: this screen is deliberately exempt from the liquid glass
// redesign. Nothing here is translucent, animated, or layered over the ambient
// mesh — the Scaffold paints its own opaque ground so the colour field behind
// the rest of the app cannot bleed through and reduce contrast. Someone reading
// this screen is frightened and in a hurry; legibility beats beauty.
import 'package:family_veda/theme/app_theme.dart';
import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';

class EmergencyScreen extends StatelessWidget {
  const EmergencyScreen({super.key});

  Future<void> _callEmergency(BuildContext context) async {
    final launched = await launchUrl(Uri(scheme: 'tel', path: '1990'));
    if (!launched && context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Call Suwa Seriya directly on 1990.')),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final ground = isDark ? AppColors.surfaceDark : Colors.white;
    final ink = isDark ? AppColors.textDark : AppColors.text;
    final emergency = isDark ? AppColors.emergencyDark : AppColors.emergency;
    final panel = isDark ? AppColors.backgroundDark : const Color(0xFFF4F6F6);
    final rule = isDark ? AppColors.borderDark : AppColors.border;

    return Scaffold(
      // Opaque on purpose. Do not make this transparent.
      backgroundColor: ground,
      appBar: AppBar(
        title: const Text('Emergency referral'),
        backgroundColor: emergency,
        foregroundColor: Colors.white,
        elevation: 0,
      ),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            Semantics(
              header: true,
              child: Text(
                'Seek immediate in-person medical care.',
                style: TextStyle(
                  color: emergency,
                  fontSize: 24,
                  fontWeight: FontWeight.w600,
                  height: 1.2,
                ),
              ),
            ),
            const SizedBox(height: 12),
            Text(
              'Do not wait for an online response. Contact emergency services '
              'or go to the nearest hospital.',
              style: TextStyle(fontSize: 16, height: 1.5, color: ink),
            ),
            const SizedBox(height: 20),
            ElevatedButton.icon(
              key: const Key('call_1990_button'),
              style: ElevatedButton.styleFrom(
                backgroundColor: emergency,
                foregroundColor: Colors.white,
                minimumSize: const Size(44, 56),
              ),
              onPressed: () => _callEmergency(context),
              icon: const Icon(Icons.call),
              label: const Text('Call Suwa Seriya 1990'),
            ),
            const SizedBox(height: 20),
            Text(
              'Nearest hospitals',
              style: Theme.of(
                context,
              ).textTheme.titleLarge?.copyWith(color: ink),
            ),
            const SizedBox(height: 8),
            _SolidPanel(
              fill: panel,
              border: rule,
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Icon(Icons.local_hospital_outlined, color: ink),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Use your phone maps to find the nearest hospital',
                          style: TextStyle(
                            fontSize: 15,
                            fontWeight: FontWeight.w600,
                            color: ink,
                          ),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          'Location results depend on your current position.',
                          style: TextStyle(
                            fontSize: 13,
                            height: 1.45,
                            color: isDark
                                ? AppColors.mutedDark
                                : AppColors.muted,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 12),
            _SolidPanel(
              fill: panel,
              border: rule,
              child: Text(
                'This referral screen does not confirm that a message was '
                'sent. Call emergency services now and contact the Family '
                'Head directly when it is safe to do so.',
                style: TextStyle(fontSize: 15, height: 1.5, color: ink),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _SolidPanel extends StatelessWidget {
  const _SolidPanel({
    required this.child,
    required this.fill,
    required this.border,
  });

  final Widget child;
  final Color fill;
  final Color border;

  @override
  Widget build(BuildContext context) => Container(
    width: double.infinity,
    padding: const EdgeInsets.all(16),
    decoration: BoxDecoration(
      color: fill,
      border: Border.all(color: border),
      borderRadius: const BorderRadius.all(Radius.circular(16)),
    ),
    child: child,
  );
}
